<?php

namespace App\Support;

/**
 * Portfolio / sample-work content (visualization renders, permit sets, Revit + scan-to-BIM sheets,
 * case-study media). Image files live in public/assets/img/work/ and are generated by
 * tools/build-work-assets.mjs, which also writes resources/data/work-manifest.json (pixel sizes).
 *
 * PRIVACY NOTE: sheets are published cropped/redacted (no owner names, addresses, contractor details
 * or client logos) and cover sheets / site plans are intentionally omitted.
 */
class Portfolio
{
    private static ?array $manifest = null;

    /** Resolve an image key (e.g. "viz/bedroom") to URLs + sizes. Thumb = 800w variant. */
    public static function img(string $key): array
    {
        if (self::$manifest === null) {
            $file = resource_path('data/work-manifest.json');
            self::$manifest = is_file($file) ? (json_decode(file_get_contents($file), true) ?: []) : [];
        }
        $m = self::$manifest["{$key}"] ?? ['w' => 1600, 'h' => 1000, 'tw' => 800, 'th' => 500];

        return [
            'key'   => $key,
            'src'   => asset_v("assets/img/work/{$key}.webp"),
            'thumb' => asset_v("assets/img/work/{$key}-800.webp"),
            'base'  => "assets/img/work/{$key}",           // for partials that expect "<base>.webp" / "<base>-800.webp"
            'w'     => $m['w'], 'h' => $m['h'], 'tw' => $m['tw'], 'th' => $m['th'],
        ];
    }

