    /* ------------------------------------------------------------------ Scan-to-BIM before / after */

    public static function scanPairs(): array
    {
        $mk = fn ($key, $ratio, $label, $altA, $altB) => [
            'label' => $label, 'ratio' => $ratio, 'a' => self::img("scan/{$key}-cloud"), 'b' => self::img("scan/{$key}-model"), 'altA' => $altA, 'altB' => $altB,
        ];

        return [
            $mk('house-1', '1600 / 1000', 'View 1: site', 'Coloured point cloud of a historic brick house and its grounds', 'Revit existing-conditions model of the same house and grounds'),
            $mk('house-2', '730 / 330', 'View 2: detail', 'Point cloud close-up of the house front, chimneys and entrance', 'Revit model close-up of the same house front, chimneys and entrance'),
        ];
    }

    public static function scanFacade(): array
    {
        return ['a' => self::img('scan/facade-cloud'), 'b' => self::img('scan/facade-model'),
            'altA' => 'Point cloud of a street facade with carved stone entrance details', 'altB' => 'Revit model of the same street facade with the entrance details modeled'];
    }

